'use server'

import { prisma } from '@/lib/db'
import { Status } from '@/generated/prisma'
import { revalidatePath } from 'next/cache'

export async function updateVehicleKm(vehicleId: string, newKm: number) {
  const vehicle = await prisma.vehicle.update({
    where: { id: vehicleId },
    data: { currentKm: newKm },
  })
  revalidatePath('/')
  return vehicle
}

export async function createMaintenanceExpense(
  maintenanceId: string,
  itemName: string,
  itemCost: number,
  isOriginalPart: boolean = false
) {
  const expense = await prisma.projectExpense.create({
    data: {
      maintenanceId,
      itemName,
      itemCost,
      isOriginalPart,
    },
  })
  revalidatePath('/')
  return expense
}

export async function updateMaintenanceStatus(
  maintenanceId: string,
  status: Status
) {
  const maintenance = await prisma.maintenanceLog.update({
    where: { id: maintenanceId },
    data: { status },
  })
  revalidatePath('/')
  return maintenance
}

export async function createMaintenanceLog(data: {
  vehicleId: string
  type: 'PREVENTIVE' | 'CORRECTIVE' | 'UPGRADE'
  description: string
  kmAtService: number
  cost?: number
  diagramCode?: string
}) {
  const maintenance = await prisma.maintenanceLog.create({
    data: {
      vehicleId: data.vehicleId,
      type: data.type,
      description: data.description,
      kmAtService: data.kmAtService,
      cost: data.cost,
      diagramCode: data.diagramCode,
      status: 'PENDING',
    },
  })
  revalidatePath('/')
  return maintenance
}

export async function getVehicleWithData(vehicleId: string) {
  return prisma.vehicle.findUnique({
    where: { id: vehicleId },
    include: {
      maintenanceLogs: {
        include: {
          expenses: true,
        },
        orderBy: {
          createdAt: 'desc',
        },
      },
    },
  })
}

export async function getPendingMaintenance(vehicleId: string) {
  return prisma.maintenanceLog.findMany({
    where: {
      vehicleId,
      status: 'PENDING',
    },
    include: {
      expenses: true,
    },
    orderBy: {
      createdAt: 'desc',
    },
  })
}

export async function searchTechnicalSpecs(query: string) {
  return prisma.technicalSpec.findMany({
    where: {
      OR: [
        { component: { contains: query, mode: 'insensitive' } },
        { category: { contains: query, mode: 'insensitive' } },
        { notes: { contains: query, mode: 'insensitive' } },
      ],
    },
  })
}
